// Check for keyword density in work experience descriptions
const experienceTexts = workExperience
  .map((exp) => `${exp.position} ${exp.company} ${exp.description}`)
  .join(' ')
  .toLowerCase()

const commonActionVerbs = [
  'led', 'managed', 'developed', 'created', 'implemented', 'designed', 'built',
  'improved', 'optimized', 'increased', 'decreased', 'achieved', 'accomplished',
  'coordinated', 'collaborated', 'initiated', 'launched', 'delivered', 'executed',
]

const actionVerbCount = commonActionVerbs.filter((verb) =>
  new RegExp(`\\b${verb}\\b`).test(experienceTexts)
).length

if (actionVerbCount < 5) {
  checks.push({
    category: 'Content Quality',
    check: 'Action Verbs',
    status: 'warning',
    message: `Only ${actionVerbCount} action verbs found in work experience. Use more impactful language.`,
    suggestion: 'Use strong action verbs like "led", "managed", "developed", "implemented" in your job descriptions.',
  })
}

